def save_json(path, value):
    temp = path.with_suffix(path.suffix + ".tmp")
    temp.write_text(json.dumps(value, ensure_ascii=False, indent=2))
    temp.replace(path)


GRABAR = True
IDIOMA = "es"                       # the menu's language (--idioma)
PRES = ROOT / "c64/presentacion/generado_p500"
DISCO = ROOT / "c64/discop500/abadia128ks_p500.d80"
_AB = V.etiquetas(str(PRES / "abadia.lbl"))
OPCIONES = _AB["_opciones500"]       # the P500 menu's options (c64/presentacion/menu500.c), bank 0
MENU_TECLA = _AB["_cgetc"]           # the menu waits for a key in cc65's cgetc
READY = bytes([0x12, 0x05, 0x01, 0x04, 0x19, 0x2E])    # "ready." in screen codes


def juego_dir():
    return ROOT / "c64/juego_final" / ("p500_en" if IDIOMA == "en" else "p500")


def ready(v):
    """how many "ready." the P500's text screen shows ($D000 of bank 15: the monitor's I/O bank, 16)"""
    _, c = v.orden(V.CMD_MEM_GET, struct.pack("<BHHBH", 0, 0xD000, 0xD3E7, 0, 16))
    return c[2:].count(READY)


def teclea_kernal(v, texto):
    """into the KERNAL's keyboard buffer of bank 15 ($03AB, its count $D1: ten places, $03B5 on is a vector), in
    pieces taken by the screen editor one after the other"""
    for k in range(0, len(texto), 10):
        p = texto[k:k + 10].encode("ascii")
        v.orden(V.CMD_MEM_SET, struct.pack("<BHHBH", 0, 0x03AB, 0x03AB + len(p) - 1, 0, 15) + p)
        v.orden(V.CMD_MEM_SET, struct.pack("<BHHBH", 0, 0xD1, 0xD1, 0, 15) + bytes([len(p)]))
        v.orden(V.CMD_EXIT)
        time.sleep(0.4)
        v.orden(V.CMD_PING)


def espera_ready(v, antes, limite=300):
    t0 = time.monotonic()
    while time.monotonic() - t0 < limite:
        n = ready(v)
        if n > antes:
            return n
        v.orden(V.CMD_EXIT)
        time.sleep(0.5)
        v.orden(V.CMD_PING)
    raise RuntimeError("the P500 shows no ready.")


def arranca_p500(v):
    """the P500's start: BASIC ready, DLOAD"ABADIA", ready again, RUN: the start menu waiting for a key"""
    v.orden(V.CMD_PING)
    n = espera_ready(v, 0)
    teclea_kernal(v, 'DLOAD"ABADIA"\r')
    espera_ready(v, n)
    p = b"RUN\r"
    v.orden(V.CMD_MEM_SET, struct.pack("<BHHBH", 0, 0x03AB, 0x03AB + len(p) - 1, 0, 15) + p)
    v.orden(V.CMD_MEM_SET, struct.pack("<BHHBH", 0, 0xD1, 0xD1, 0, 15) + bytes([len(p)]))
    v.hasta(MENU_TECLA, limite=900)


def tecla_cc65(v, c):
    """a key into cc65's buffer (the menu and the presentation read it with cgetc / kbhit)"""
    v.orden(V.CMD_MEM_SET, struct.pack("<BHHBH", 0, _AB["keybuf"], _AB["keybuf"], 0, 0) + c.encode("ascii"))
    v.orden(V.CMD_MEM_SET, struct.pack("<BHHBH", 0, _AB["keyidx"], _AB["keyidx"], 0, 0) + b"\x01")


def alturas_c128(pil, engine):
    """the pilot's height maps from the C128's own lists (the full game's), not from its 64 KiB CPC image"""
    import mapa_alturas
    inc = {}
    for l in (juego_dir() / "mapa64.inc").read_text().splitlines():
        q = l.split()
        if len(q) >= 3 and q[1] == "=" and q[2].startswith("$"): inc[q[0]] = int(q[2][1:], 16)
    mapa_alturas.LISTS = {k: inc[f"D64_CHR_FLOOR{k}_HEIGHTS"] for k in range(3)}
    pil.floor_map = lambda ram, floor: mapa_alturas.floor_map(engine.native, floor)


def piloto_completo(pil):
    """the full game's pilot: the C64 one with the PC's fifth night (abadia-english/partida/piloto/ajustes_pc.py, the
    pilot that won the PC's full game): taking the second key on day 5 makes the abbot hunt Guillermo at once, and
    in the full game's longer abbey the planner's walk back to the cell is caught (the C128 rehearsal:
    dead at BEh, 2Ch, night 5); the way back is walked with the keys, ahead of the abbot by the east gap (C8h, 34h)"""
    class PilotoCompleto(pil.Pilot):
        def follow(self, who, until, limit=5000):
            """(ABADIA_SEGUIR_TECLAS=1) following with the keys: the planner chooses the way, Guillermo walks it
            with the keys (0.5 cells a frame, the abbot's pace; under the planner's own walk he lags and leaves the
            abbot's box, ai_guillermo_is_close: obsequium - 2 each time)"""
            if os.environ.get("ABADIA_SEGUIR_TECLAS") != "1":
                return pil.Pilot.follow(self, who, until, limit)
            motor = self.e
            class SinMeta:
                def __getattr__(s, n):
                    if n == "set_guillermo_goal": raise AttributeError(n)
                    return getattr(motor, n)
            # the keys first; a stretch with no arrival (a stair the keys' route does not climb) goes to the
            # planner's own walk, and back (ABADIA_SEGUIR_TROZO iterations a stretch)
            trozo, usados, teclas = int(os.environ.get("ABADIA_SEGUIR_TROZO", "250")), 0, True
            while usados < limit:
                if teclas: self.e = SinMeta()
                try:
                    return pil.Pilot.follow(self, who, until, min(trozo, limit - usados))
                except pil.Blocked as e:
                    if "Seguir al personaje" not in str(e): raise
                    usados += trozo
                    teclas = not teclas
                finally:
                    self.e = motor
                self.log("Seguimiento: " + ("con las teclas" if teclas else "con el planificador"))
            raise pil.Blocked(f"Seguir al personaje {who}: {self.state()}")
        def sleep(self):
            """the C64 pilot's sleep() with the PC's fifth night (the day is read after midnight, as there)"""
            self.goto(0xA8, 0x1C)
            self.until(lambda: self.b(0x28D2) == 0)
            if self.b(0x28D1) in (3, 5, 6):
                self.until(lambda: self.b(0x385F) == 4)
                self.until(lambda: not self.b(0x28F2))
                self.step(("n",))
                self.step(("n",))
                if self.b(0x28D1) == 3:
                    self.take(3)
                    self.return_cell()
                elif self.b(0x28D1) == 5:
                    self.take(4)
                    self.log("Llave en la mano: el abad nos busca; volvemos a la celda con las teclas")
                    self.goto(0xC8, 0x34, local=True)
                    self.goto(0xA8, 0x1C, z=2, local=True)
                elif self.b(0x28D1) == 6:
                    self.take(5)
                    self.take(2)
                    self.goto(0x56, 0x2D, z=0)
                    self.log("Esperamos el alba en el ala oeste, fuera de la ronda del abad")
                    self.until(lambda: int.from_bytes(self.e.read(0x28D7, 2), "little") < 300)
                    self.goto(0x60, 0x2A, z=0)
                    self.goto(0x84, 0x4B, 1, local=True, bounds=(0x60, 1, 254, 254))
            self.until(lambda: self.b(0x28D2) == 1, keys=("s",))
            self.log("Amanece")
    return PilotoCompleto


def nuevo_oraculo(viejo):
    """the planner's VICE closed (it may have died) and another one started the same way"""
    try:
        viejo.orden(V.CMD_QUIT)
    except Exception:
        pass
    try:
        viejo.proc.kill()
        viejo.proc.wait(timeout=20)
        viejo.s.close()
        if viejo.xvfb:
            viejo.xvfb.terminate()
            viejo.xvfb.wait(timeout=10)
    except Exception:
        pass
    nuevo = Visible(viejo.salida_dir, warp=True, disk=viejo.disco)
    nuevo.oraculo = True
    return nuevo


def marca(out, nombre):
    """the moment of an event of the session (wall clock), for monta.py"""
    path = out / "marcas.json"
    marcas = json.loads(path.read_text()) if path.exists() else []
    marcas.append([nombre, time.time()])
    save_json(path, marcas)
    print("marca", nombre, flush=True)


def espera(v, segundos):
    """the machine runs on for a while (the menu, a page held), counted in the KERNAL's jiffies (the store to
    $A2, 60 a second), so that the rehearsal in warp and the recording in real time reach the game at the same
    emulated moment (wall-clock waits made them differ: the game's random numbers come from the machine's time)"""
    # (the P500: cc65's own clock, its `time` in bank 0's zero page, counted up by its 50 Hz interrupt, kudtim.s)
    _, c = v.orden(V.CMD_CHECKPOINT_SET, struct.pack("<HHBBBBB", _AB["time"], _AB["time"], 1, 1, 2, 0, 0))
    num = struct.unpack("<I", c[:4])[0]
    try:
        for _ in range(int(segundos * 50)):
            v.golpes.discard(num)
            v.orden(V.CMD_EXIT)
            v.s.settimeout(30)
            while num not in v.golpes:
                v._respuesta()
            v.s.settimeout(None)
    finally:
        v.s.settimeout(None)
        v.orden(V.CMD_CHECKPOINT_DELETE, struct.pack("<I", num))


def watch_recording(out, proof):
    """Recover once from the already validated fifth-day failure; alert otherwise."""
    out, proof = out.resolve(), proof.resolve()
    if out.parent != RECORDINGS or not out.name.startswith("grabacion_"):
        raise ValueError("Solo se supervisan grabaciones de este piloto")
    validated = json.loads((proof / "estado.json").read_text())
    if validated.get("phase") != "completo" or validated.get("final_pages", 0) < 12:
        raise ValueError("Falta una validación nativa completa del final")
    source = HERE / "piloto.py"
    digest = hashlib.sha256(source.read_bytes()).hexdigest()
    journal_path = out / "vigilante.json"
    journal = json.loads(journal_path.read_text()) if journal_path.exists() else dict(retries=0)
    journal.update(validation=str(proof), pilot_sha256=digest)
    save_json(journal_path, journal)
    previous = None
    while True:
        status_file = out / "estado.json"
        if not status_file.exists():
            time.sleep(2)
            continue
        state = json.loads(status_file.read_text())
        marker = (state.get("phase"), state.get("day"), state.get("hour"), state.get("goal"))
        if marker != previous:
            print(json.dumps(state, ensure_ascii=False), flush=True)
            previous = marker
        if state.get("phase") == "completo":
            journal["complete"] = True
            save_json(journal_path, journal)
            return 0
        if state.get("phase") == "bloqueado":
            known = (state.get("goal") == "dia5_investigacion" and state.get("day") == 5
                     and state.get("hour") == 4 and "muerto" in state.get("reason", ""))
            unchanged = hashlib.sha256(source.read_bytes()).hexdigest() == digest
            if known and unchanged and journal["retries"] == 0:
                journal["retries"] = 1
                journal["recovery"] = state
                save_json(journal_path, journal)
                save_json(out / "CONTINUAR.json", dict(action="retry", validation=str(proof)))
                print("Recuperación del quinto día con la coordinación de Adso ya validada en VICE", flush=True)
                while json.loads(status_file.read_text()).get("phase") == "bloqueado":
                    time.sleep(1)
            else:
                print("AVISO: el bloqueo requiere intervención del supervisor", flush=True)
                return 2
        time.sleep(2)


class Visible(V.Vice):
    def __init__(self, out, warp=False, disk=None, video=None):
        Visible.n = getattr(Visible, "n", 0) + 1         # (the rehearsal's two VICEs, both in warp: a port each)
        self.puerto = 6520 + os.getpid() % 500 * 2 + Visible.n if warp else int(os.environ.get("ABADIA_PUERTO", "6519"))
        try:                                          # (a VICE left on that port would answer instead of ours)
            socket.create_connection(("127.0.0.1", self.puerto), timeout=0.5).close()
            raise RuntimeError(f"the monitor port {self.puerto} is in use: another VICE is listening there")
        except OSError:
            pass
        self.casa = None
        self.registro = (out / "vice.log").open("a")
        self.salida_dir, self.disco = out, disk          # (a new oracle, the same as this one: nuevo_oraculo)
        env = dict(os.environ)
        env.update(DISPLAY=os.environ.get("ABADIA_DISPLAY", ":99"), XDG_RUNTIME_DIR="/run/user/1000", PULSE_SERVER="unix:/run/user/1000/pulse/native")
        if os.environ.get("ABADIA_XAUTHORITY"):
            env["XAUTHORITY"] = os.environ["ABADIA_XAUTHORITY"]   # the desktop (hal9000c: plasmashell's)
        else:
            env.pop("XAUTHORITY", None)
        self.env = env
        self.audio_modules = []
        self.recording = None
        self.xvfb = None
        if warp:
            self.xvfb = subprocess.Popen(["Xvfb", "-displayfd", "1", "-screen", "0", "1280x1024x24",
                                           "-nolisten", "tcp"], stdout=subprocess.PIPE, stderr=self.registro)
            display = self.xvfb.stdout.readline().decode().strip()
            if not display:
                raise RuntimeError("No ha arrancado el escritorio de pruebas")
            env["DISPLAY"] = ":" + display
            env.pop("XAUTHORITY", None)
        if not warp and GRABAR:
            sink = "abadia_grabacion_" + str(os.getpid())
            self.sink = sink
            for args in (["module-null-sink", "sink_name=" + sink, "rate=48000", "channels=2"],):   # (no loopback to the speakers: two recordings at once)
                number = subprocess.check_output(["pactl", "load-module", *args], env=env, text=True).strip()
                self.audio_modules.append(number)
            env["PULSE_SINK"] = sink
        cmd = ["xcbm5x0", "-default", "-seed", "64", "-model", "510", "-ramsize", "128", "-pal",
               "-binarymonitor", "-binarymonitoraddress", f"ip4://127.0.0.1:{self.puerto}",
               "-speed", "100", "+autostart-warp", "-warp" if warp else "+warp",
               "-VICIIfilter", "0" if warp else "1", "-VICIIglfilter", "0", "-VICIIdscan",
               "-sounddev", "dummy" if warp else "pulse", "-sound",
               "-drive8type", "8050", "-drive8truedrive",
               "-8", str(disk or DISCO)]
        if not warp:
            cmd += os.environ.get("ABADIA_VICE_EXTRA", "").split()
        self.proc = subprocess.Popen(cmd, env=env, stdout=self.registro, stderr=subprocess.STDOUT)
        self.s = None
        for _ in range(150):
            try:
                self.s = socket.create_connection(("127.0.0.1", self.puerto), timeout=2)
                self.s.settimeout(None)
                self.s.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
                break
            except OSError:
                if self.proc.poll() is not None:
                    raise RuntimeError("VICE no ha arrancado")
                time.sleep(0.1)
        if self.s is None:
            raise RuntimeError("Monitor de VICE no disponible")
        self.id, self.eventos, self.parado, self.pc = 0, [], False, None
        self.paradas, self.golpes, self.jams = 0, set(), 0
        arranca_p500(self)                      # DLOAD, RUN: the menu
        if not warp and GRABAR:
            self.record(out, video)

    def restaura(self, nombre):
        """VICE 3.10's xcbm5x0 restores the 6526 with its interrupt pending and TPI 1 waiting for an edge that does not
        come (checked: ICR 81h, no tick afterwards): the game's own acknowledgement after the restore (the 6526's ICR
        read, TPI 1's AIR written back, the ICR read again, through the monitor's I/O bank 16) brings the tick back
        (checked).  Not on the planner's VICE, whose code always ran without it."""
        V.Vice.restaura(self, nombre)
        if not getattr(self, "oraculo", False):
            self.orden(V.CMD_MEM_GET, struct.pack("<BHHBH", 1, 0xDC0D, 0xDC0D, 0, 16))
            _, c = self.orden(V.CMD_MEM_GET, struct.pack("<BHHBH", 0, 0xDE07, 0xDE07, 0, 16))
            self.orden(V.CMD_MEM_SET, struct.pack("<BHHBH", 0, 0xDE07, 0xDE07, 0, 16) + c[2:3])
            self.orden(V.CMD_MEM_GET, struct.pack("<BHHBH", 1, 0xDC0D, 0xDC0D, 0, 16))

    def record(self, out, video=None):
        target = Path(video).resolve() if video else out / "partida.mkv"
        window = None
        for _ in range(80):
            result = subprocess.run(["xdotool", "search", "--onlyvisible", "--pid", str(self.proc.pid)],
                                    env=self.env, text=True, capture_output=True)
            if result.returncode == 0 and result.stdout.strip():
                window = result.stdout.splitlines()[-1]
                break
            time.sleep(0.1)
        if window is None:
            raise RuntimeError("No encuentro la ventana visible de VICE")
        subprocess.run(["xdotool", "windowfocus", window], env=self.env, check=False)     # the virtual display has no window manager
        self.record_log = (out / "ffmpeg.log").open("w")
        cmd = ["ffmpeg", "-hide_banner", "-nostdin", "-n", "-thread_queue_size", "1024",
               "-f", "x11grab", "-framerate", "50", "-draw_mouse", "0", "-window_id", window,
               "-i", self.env["DISPLAY"], "-thread_queue_size", "1024", "-f", "pulse", "-i", self.sink + ".monitor",
               "-vf", "pad=ceil(iw/2)*2:ceil(ih/2)*2", "-c:v", "libx264", "-preset", "veryfast",
               "-crf", "16", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "192k",
               "-ar", "48000", "-f", "matroska", str(target)]
        self.recording = subprocess.Popen(cmd, env=self.env, stdout=self.record_log, stderr=subprocess.STDOUT)
        marca(out, "grabacion")
        time.sleep(1)
        if self.recording.poll() is not None:
            raise RuntimeError("La grabación no ha arrancado: revisar ffmpeg.log")
        save_json(out / "grabacion.json", dict(source=str(target),
                  mp4=str(target.with_suffix(".mp4")) if video else str(out / "partida_completa.mp4"),
                  ffmpeg_pid=self.recording.pid, vice_pid=self.proc.pid,
                  speed_percent=100, warp=False, crt_filter=True, double_scan=True))
        print("Grabando vídeo y audio:", target, flush=True)

    def stop_record(self):
        if self.recording and self.recording.poll() is None:
            self.recording.send_signal(signal.SIGINT)
            self.recording.wait(timeout=20)
            self.record_log.close()


class Native(piloto.NPCNavigation):
    def __init__(self, vice, out, oracle=None):
        self.v, self.out, self.frame = vice, out, 472
        self.oracle = oracle
        self.recovery = oracle is not None
        self.phase_count = 0
        self.phase_name = "inicio"
        self.labels = V.etiquetas(str(juego_dir() / "juego.lbl"))
        self.ram_bank = D.bancos(vice)["ram00"]
        self.points = D.Puntos(vice)
        self.points.pon(self.labels["game_input_and_mirror"] + 3)
        self.points.pon(self.labels["plat_final"])
        self.maps = []
        for line in (juego_dir() / "mapa64.tsv").read_text().splitlines():
            if line.startswith("#") or not line.strip():
                continue
            name, old, length, new, nlength, mode, zona, *_ = line.split()
            if mode == "copia" and length == nlength and zona != "banco1":
                self.maps.append((int(old, 16), int(length), int(new, 16)))
        self.base = bytearray((ROOT / "../data/cpc64/inicio_juego/ram.bin").read_bytes())
        self.previous = bytes([255] * 10)
        self.inputs = []
        self.started = time.monotonic()
        self.last_hour = None
        self.last_status = 0
        self.oracle_calls = 0
        self.adso_target = None
        self.g_mode = False
        self.g_stream = bytes(45)
        self.points.siguiente()
        self.refresh()

    def refresh(self):
        self.native = bytearray(D.lee(self.v, self.ram_bank, 0, 65535))
        self.virtual = bytearray(self.base)
        for old, length, new in self.maps:
            self.virtual[old:old + length] = self.native[new:new + length]

    def read(self, address, length=1):
        return bytes(self.virtual[address:address + length])

    def translate(self, address):
        for old, length, new in self.maps:
            if old <= address < old + length:
                return new + address - old
        raise ValueError(f"Dato CPC sin correspondencia: {address:04X}")

    def put(self, address, data):
        self.v.orden(V.CMD_MEM_SET, struct.pack("<BHHBH", 0, address, address + len(data) - 1,
                                                0, self.ram_bank) + bytes(data))

    def g_enabled(self, value):
        self.g_mode = value

    def g_reset(self):
        a = self.translate(piloto.CHARS[0] + 9)
        self.put(a, b"\x80")
        self.native[a] = 128
        self.virtual[piloto.CHARS[0] + 9] = 128

    def g_load(self, stream):
        self.g_stream = stream
        a = self.translate(piloto.CHARS[0] + 9)
        self.put(a, b"\0\0\0")
        self.native[a:a + 3] = b"\0\0\0"
        self.virtual[piloto.CHARS[0] + 9:piloto.CHARS[0] + 12] = b"\0\0\0"

    def g_install(self):
        workspace = self.translate(0x3568)
        record = self.translate(piloto.CHARS[0])
        entry = self.translate(0x2703) + 4
        self.g_saved = (bytes(self.native[workspace:workspace + 45]),
                        bytes(self.native[record + 12:record + 14]), bytes(self.native[entry:entry + 2]))
        self.put(workspace, self.g_stream)
        self.put(record + 12, struct.pack("<H", workspace))
        self.put(entry, struct.pack("<H", self.labels["chr_ai_follow_commands"]))
        self.points.pon(self.labels["game_run_npc_behaviours"])

    def g_restore(self):
        workspace = self.translate(0x3568)
        record = self.translate(piloto.CHARS[0])
        entry = self.translate(0x2703) + 4
        data, pointer, behaviour = self.g_saved
        self.put(workspace, data)
        self.put(record + 12, pointer)
        self.put(entry, behaviour)
        self.points.quita(self.labels["game_run_npc_behaviours"])

    def activate(self, who, stream):
        chr = self.translate(piloto.CHARS[who])
        pointer = int.from_bytes(self.native[chr + 12:chr + 14], "little")
        self.put(pointer, stream)
        self.put(chr + 9, b"\0\0\0")
        self.refresh()

    def adso_goal(self, x, y, z, orientation):
        self.adso_place_saved = self.read(0x3861, 3)
        self.adso_target = bytes((x, y, z | (orientation << 6)))
        self.put(self.translate(piloto.CHARS[1] + 9), b"\x80")
        self.points.pon(self.labels["camino_drive_ai_done"])

    def adso_release(self):
        self.points.quita(self.labels["camino_drive_ai_done"])
        self.adso_target = None
        self.put(self.translate(0x3861), self.adso_place_saved)
        self.put(self.translate(0x3860), b"\xff")
        self.put(self.translate(piloto.CHARS[1] + 9), b"\x80")
        self.refresh()

    def generate(self, x, y, z, orientation=1, who=0, follow=None):
        """Run the real 6510 NPC planner, retaining only its proposed commands.

        A full machine snapshot protects stack, all NPCs, their workspaces, SID,
        CIA time and the disk drive. Nothing from the planning call is kept in
        the actual game; its normal movement routine receives the chosen keys.
        """
        checkpoint = self.out / "planificador_temporal.vsf"
        pc_before = self.v.registros()[3]
        self.v.instantanea(str(checkpoint))
        actual = self.v
        if self.oracle is not None:
            try:
                self.oracle.restaura(str(checkpoint))
            except Exception as exc:                # (VICE's xcbm5x0 fails a restore after many of them, the
                print("Oráculo: restauración fallida, otro VICE:", exc, flush=True)   # snapshot itself good)
                self.oracle = nuevo_oraculo(self.oracle)
                self.oracle.restaura(str(checkpoint))
            self.v = self.oracle
        result = None
        try:
            chr = self.translate(piloto.CHARS[who])
            if who == 0 and getattr(self, "ignore_adso", False):
                self.put(self.translate(piloto.CHARS[1] + 2), b"\0")
            workspace = self.translate(0x3568)
            target = self.translate(0x0203)
            self.put(chr + 12, struct.pack("<H", workspace))
            self.put(chr + 9, b"\x80")
            self.put(self.translate(0x0600), b"\0")
            self.put(self.translate(0x28FA), b"\0")
            self.put(self.translate(0x0213), struct.pack("<H", target))
            if follow is None:
                targets = bytes((x, y, z | (orientation << 6), 255))
            else:
                _, gx, gy, _ = self.read(piloto.CHARS[who] + 1, 4)
                candidates = piloto.follow_targets(x, y, self.virtual[piloto.CHARS[follow] + 1], gx, gy)
                targets = bytes(v for tx, ty in candidates for v in (tx, ty, z)) + b"\xff"
            self.put(target, targets)
            mask = 0x28 | self.virtual[0x292A] | self.virtual[0x292D]
            for door in range(0x2B35, 0x2B58, 5):
                flags = self.virtual[door + 1]
                if flags & 64:
                    mask |= flags & 31
            code = bytearray((0x78, 0xD8, 0xA9, 0x00, 0x85, 0x01, 0xA9, mask, 0x85, 2))   # (the 6509's indirect bank register: bank 0)
            def call(name):
                code.extend((0x20, self.labels[name] & 255, self.labels[name] >> 8))
            call("obj_set_door_permissions")
            for reg, value in ((8, target), (10, chr)):
                code.extend((0xA9, value & 255, 0x85, reg, 0xA9, value >> 8, 0x85, reg + 1))
            call("chr_path_find")
            stop = 0x100 + len(code)
            code.extend((0x4C, stop & 255, stop >> 8))
            self.put(0x100, code)
            self.v.pon_pc(0x100)
            D.corre_hasta(self.v, stop, limite=10)
            if not D.lee(self.v, self.ram_bank, chr + 9, chr + 9)[0] & 128:
                result = D.lee(self.v, self.ram_bank, workspace, workspace + 44)
        finally:
            self.v = actual
            if self.oracle is None:
                self.v.restaura(str(checkpoint))
        self.oracle_calls += 1
        if self.oracle_calls == 1:
            assert self.v.registros()[3] == pc_before, "El planificador no ha restaurado la CPU"
            assert D.lee(self.v, self.ram_bank, 0, 65535) == self.native, "El planificador ha alterado la partida"
            print("IA: planificador 6510 original, CPU y RAM restauradas sin diferencias", flush=True)
        return result

    def step(self, keys=()):
        self.prepare_guillermo()
        if self.g_mode:
            keys = (*keys, "up")
            if self.virtual[0x37DC] == 0:
                self.g_install()
        keys = self.team_inputs(keys)
        down = bytearray([255] * 10)
        for key in keys:
            row, bit = piloto.KEYS[key]
            down[row] &= ~(1 << bit)
        pending = bytes((now | (255 ^ before)) & 255 for now, before in zip(down, self.previous))
        # Same decoded input bitmaps as the real keyboard; all game rules remain untouched.
        self.v.orden(V.CMD_MEM_SET, struct.pack("<BHHBH", 0, 0x05BC, 0x05CF, 0, self.ram_bank)
                     + down + pending)
        self.previous = bytes(down)
        self.inputs.append((self.frame, tuple(keys)))
        while True:
            pc = self.points.siguiente(limite=20)
            if pc == self.labels["game_run_npc_behaviours"]:
                self.g_restore()
                continue
            if pc != self.labels.get("camino_drive_ai_done"):
                break
            if self.adso_target is not None and D.lee(self.v, self.ram_bank, 0xA5, 0xA5)[0] == 4:
                self.put(self.translate(0x3860), b"\0")
                self.put(self.translate(0x3861), self.adso_target)
        self.frame += 1
        if pc == self.labels["plat_final"]:
            self.points.fuera()
            raise StopIteration("Final alcanzado por el juego real")
        self.refresh()
        if os.environ.get("ABADIA_TRAZA_OBS") == "1":           # (a diagnosis: every frame the obsequium falls)
            obs = self.virtual[0x28D0]
            if getattr(self, "_obs", None) is not None and obs < self._obs:
                g, a = self.virtual[0x2B87:0x2B87 + 5], self.virtual[0x2B87 + 45:0x2B87 + 50]
                print("OBS", self.frame, self._obs, "->", obs, "G", list(g), "abad", list(a),
                      "estado", self.virtual[0x3814], "hora", self.virtual[0x28D2], flush=True)
            self._obs = obs
        if time.monotonic() - self.last_status > 5:
            self.status("jugando")
            self.last_status = time.monotonic()
        hour = (self.virtual[0x28D1], self.virtual[0x28D2])
        if hour != self.last_hour:
            self.snapshot(f"dia{hour[0]}_hora{hour[1]}_frame{self.frame}")
            marca(self.out, f"dia{hour[0]}_hora{hour[1]}")
            self.last_hour = hour
        if self.v.recording and self.v.recording.poll() is not None:
            raise piloto.Blocked("La grabación se ha detenido")

    def status(self, phase, **extra):
        save_json(self.out / "estado.json", dict(phase=phase, frame=self.frame,
                  goal=self.phase_name,
                  day=self.virtual[0x28D1], hour=self.virtual[0x28D2],
                  G=list(self.virtual[0x2B88:0x2B8C]),
                  elapsed=round(time.monotonic() - self.started, 1), **extra))

    def snapshot(self, name):
        self.v.instantanea(str(self.out / (name + ".vsf")))
        self.v.captura(str(self.out / (name + ".png")))

    def execute_phase(self, name, callback, pilot):
        self.phase_count += 1
        self.phase_name = name
        checkpoint_name = f"fase_{self.phase_count:02}_{name}"
        self.snapshot(checkpoint_name)
        previous, frame = self.previous, self.frame
        bad = set(pilot.bad)
        attempt = 0
        while True:
            try:
                if getattr(callback, "__self__", None) is pilot:
                    getattr(pilot, callback.__name__)()
                else:
                    callback()
                return
            except StopIteration:
                raise
            except Exception as exc:
                if not self.recovery:
                    raise
                attempt += 1
                self.snapshot(f"bloqueo_{name}_{attempt}")
                self.status("bloqueado", reason=str(exc), attempt=attempt)
                save_json(self.out / "AVISO_BLOQUEO.json",
                          dict(reason=str(exc), phase=name, attempt=attempt, state=pilot.state()))
                save_json(self.out / "eventos.json", pilot.events)
                subprocess.run(["notify-send", "La Abadía: intervención del piloto", str(exc)[:300]],
                               env=self.v.env, check=False)
                print(f"BLOQUEO en {name}; VICE pausado y vídeo/audio siguen grabándose: {exc}", flush=True)
                control = self.out / "CONTINUAR.json"
                while not control.exists():
                    if self.v.recording and self.v.recording.poll() is not None:
                        raise RuntimeError("La grabación se ha detenido durante la recuperación")
                    time.sleep(1)
                command = json.loads(control.read_text())
                control.rename(self.out / f"orden_{name}_{attempt}.json")
                if command.get("action") != "retry":
                    raise RuntimeError("El supervisor ha solicitado detener la sesión") from exc
                global piloto
                piloto = load_pilot()
                alturas_c128(piloto, self)
                pilot.__class__ = piloto_completo(piloto)
                self.points.quita(self.labels["game_run_npc_behaviours"])
                self.points.quita(self.labels["camino_drive_ai_done"])
                self.v.restaura(str(self.out / (checkpoint_name + ".vsf")))
                self.g_mode, self.g_goal, self.adso_target = False, None, None
                self.previous, self.frame = previous, frame
                pilot.bad, pilot.cooperating, pilot.directing_adso = set(bad), False, False
                self.refresh()
                self.status("jugando", recovery_attempt=attempt)
                pilot.log("Reanudación desde el punto de recuperación: " + name)


def parchment(v, labels, out, prefix):
    points = D.Puntos(v)
    points.pon(labels["_nextpage"])
    points.pon(labels["_cgetc"])
    page = 1
    while True:
        pc = points.siguiente(limite=900)
        v.captura(str(out / f"{prefix}_pagina_{page:02}.png"))
        print(f"{prefix}: página {page} completa", flush=True)
        page += 1
        if pc == labels["_cgetc"]:
            points.fuera()
            return page - 1


def parchment_final(v, labels, out):
    """the ending: its pages (nextpage), its end the loop the disk's ending stays in (it reads no key: final.c)"""
    prg = (PRES / "final.prg").read_bytes()
    base, d = prg[0] | prg[1] << 8, prg[2:]
    lazos = [base + i for i in range(len(d) - 2) if d[i] == 0x4C and d[i + 1] | d[i + 2] << 8 == base + i]
    if len(lazos) != 1:
        raise RuntimeError(f"the ending's end loop: {len(lazos)} found")
    points = D.Puntos(v)
    points.pon(labels["_nextpage"])
    points.pon(lazos[0])
    page = 1
    while True:
        pc = points.siguiente(limite=900)
        v.captura(str(out / f"final_pagina_{page:02}.png"))
        print(f"final: página {page} completa", flush=True)
        page += 1
        if pc == lazos[0]:
            points.fuera()
            return page - 1


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--disco", type=Path, default=DISCO, help="el disco del 64ks con el menú de la cinta")
    parser.add_argument("--idioma", choices=("es", "en"), default="es", help="el idioma elegido en el menú")
    parser.add_argument("--ensayo-vice", action="store_true", help="ensayo rápido sin grabar")
    parser.add_argument("--sin-grabar", action="store_true", help="la sesión visible sin grabar vídeo (para verla en el escritorio)")
    parser.add_argument("--salida", type=Path, help="directorio nuevo para estados y capturas de esta sesión")
    parser.add_argument("--video", type=Path, help="archivo MKV nuevo para grabar directamente, por ejemplo en el Escritorio")
    parser.add_argument("--reanudar", type=Path, help="snapshot de una noche, solo para ensayos")
    parser.add_argument("--desde-noche", type=int)
    parser.add_argument("--ensayar-fase", choices=("investigacion5", "espejo"))
    parser.add_argument("--vigilar", type=Path)
    parser.add_argument("--ensayo-validado", type=Path)
    parser.add_argument("--actualizar-piloto", type=int, metavar="PID",
                        help="recargar el piloto propio entre fotogramas, sin reiniciar la grabación")
    args = parser.parse_args()
    global GRABAR, IDIOMA
    GRABAR = not args.sin_grabar
    IDIOMA = args.idioma
    if args.actualizar_piloto:
        target = args.actualizar_piloto
        command = Path(f"/proc/{target}/cmdline").read_bytes().split(b"\0")
        if len(command) < 2 or Path(os.fsdecode(command[1])).resolve() != Path(__file__).resolve():
            raise ValueError("El PID no corresponde al supervisor de este proyecto")
        owner = Path(f"/proc/{target}").stat().st_uid
        if owner != ROOT.stat().st_uid or os.getuid() not in (owner, 0):
            raise ValueError("El supervisor no pertenece al propietario de este proyecto")
        sys.remote_exec(target, str(HERE / "actualizar_en_vivo.py"))
        print("Actualización encolada para el próximo fotograma del piloto", flush=True)
        return 0
    if args.vigilar:
        if not args.ensayo_validado:
            parser.error("--vigilar requiere --ensayo-validado")
        return watch_recording(args.vigilar, args.ensayo_validado)
    if args.video and (args.ensayo_vice or args.video.exists() or not args.video.parent.is_dir()):
        parser.error("--video requiere una grabación real, archivo nuevo y directorio existente")
    out = args.salida.resolve() if args.salida else RECORDINGS / (
        ("ensayo_vice_" if args.ensayo_vice else "grabacion_") + datetime.datetime.now().strftime("%Y%m%d_%H%M%S"))
    out.mkdir(parents=True)
    save_json(HERE / "activa.json", dict(directory=str(out), supervisor_pid=os.getpid(),
                                        video=str(args.video.resolve()) if args.video else None))
    save_json(out / "estado.json", dict(phase="cargando", intro_pages=0, final_pages=0))
    print("Salida:", out, flush=True)
    v = oracle = None
    try:
        if True:                                # (the P500: the planner runs in a second VICE, the rehearsal's too,
            # its snapshots restored without the game's interrupt, as it always ran; the visible one gets its
            # interrupt back after a restore: Visible.restaura)
            planning_out = out / "planificador"
            planning_out.mkdir()
            oracle = Visible(planning_out, warp=True, disk=args.disco.resolve())
            oracle.oraculo = True
        v = Visible(out, warp=args.ensayo_vice, disk=args.disco.resolve(), video=args.video)
        ab = V.etiquetas(str(PRES / "abadia.lbl"))
        fi = V.etiquetas(str(PRES / "final.lbl"))
        game = V.etiquetas(str(juego_dir() / "juego.lbl"))
        if args.reanudar:
            if not args.ensayo_vice or (args.desde_noche not in range(2, 8) and not args.ensayar_fase):
                raise ValueError("La reanudación parcial es solo para ensayos nocturnos")
            v.restaura(str(args.reanudar.resolve()))
            intro = 0
        else:
            marca(out, "menu")                              # (the start already stopped at the menu's key)
            espera(v, 6)                                    # the menu on the screen
            if IDIOMA == "en":
                tecla_cc65(v, "1")                          # option 1: the language (the menu in English)
                espera(v, 5)
                marca(out, "menu_ingles")
            ram = D.bancos(v)["ram00"]
            if D.lee(v, ram, OPCIONES, OPCIONES)[0] != (1 if IDIOMA == "en" else 0):
                raise RuntimeError("the menu's options (_opciones500) are not the language asked for")
            tecla_cc65(v, " ")
            marca(out, "menu_espacio")
            D.corre_hasta(v, ab["_musicstart"], limite=900)
            marca(out, "introduccion")
            intro = parchment(v, ab, out, "introduccion")
            marca(out, "introduccion_fin")
            tecla_cc65(v, " ")
            marca(out, "carga_juego")
            D.corre_hasta(v, ab["_gameload"], limite=120)
            print("Introducción completa; cargando el juego", flush=True)
            D.corre_hasta(v, game["principal_inicio"], limite=900)
            marca(out, "juego")
        global piloto
        piloto = load_pilot()
        engine = Native(v, out, oracle=oracle)
        alturas_c128(piloto, engine)
        pilot = piloto_completo(piloto)(engine)
        engine.status("jugando", intro_pages=intro)
        try:
            if args.reanudar:
                if args.ensayar_fase == "investigacion5":
                    pilot.afternoon(5)
                    pilot.ceremony(5)
                    pilot.sleep()
                    pilot.rehearsal(start_day=6, initial=False)
                elif args.ensayar_fase == "espejo":
                    pilot.finish()
                else:
                    if pilot.b(0x28D1) != args.desde_noche or pilot.b(0x28D2) != 0:
                        raise ValueError("El snapshot no corresponde a la noche solicitada")
                    pilot.sleep()
                    pilot.rehearsal(start_day=args.desde_noche, initial=False)
            else:
                pilot.rehearsal()
            raise piloto.Blocked("La ruta preparada acaba aquí; falta la investigación final")
        except StopIteration:
            print("Victoria real: el juego carga el pergamino final desde el disco", flush=True)
            marca(out, "final_carga")
            D.corre_hasta(v, fi["_main"], limite=120)
            D.corre_hasta(v, fi["_musicstart"], limite=120)
            marca(out, "final")
            pages = parchment_final(v, fi, out)
            marca(out, "final_fin")
            engine.status("completo", intro_pages=intro, final_pages=pages)
            v.orden(V.CMD_EXIT)
            time.sleep(20)                                  # the ending's last page held (its music goes on)
            marca(out, "final_espera")
        except Exception as exc:
            engine.snapshot("bloqueo")
            engine.status("bloqueado", reason=str(exc))
            save_json(out / "AVISO_BLOQUEO.json", dict(reason=str(exc), state=pilot.state()))
            if not args.ensayo_vice:
                subprocess.run(["notify-send", "La Abadía: piloto bloqueado", str(exc)[:300]], env=v.env, check=False)
            print("BLOQUEO:", exc, flush=True)
            return 2
        finally:
            save_json(out / "controles.json", engine.inputs)
            save_json(out / "eventos.json", pilot.events)
    finally:
        if oracle:
            oracle = getattr(engine, "oracle", None) or oracle if "engine" in locals() else oracle   # (maybe a new one)
            try:
                oracle.orden(V.CMD_QUIT)
                oracle.proc.wait(timeout=20)
                oracle.s.close()
            except Exception:
                pass
            if oracle.xvfb:
                oracle.xvfb.terminate()
                oracle.xvfb.wait(timeout=10)
        if v:
            v.stop_record()
            # (the recordings run on a virtual display: their emulator is closed at the end too, so that it does
            # not keep its monitor port for the next session)
            if args.ensayo_vice or os.environ.get("ABADIA_DISPLAY", ":99") != ":0":
                v.orden(V.CMD_QUIT)
                v.proc.wait(timeout=20)
                if v.xvfb:
                    v.xvfb.terminate()
                    v.xvfb.wait(timeout=10)
            v.s.close()
            if v.audio_modules:
                default_sink = subprocess.check_output(["pactl", "get-default-sink"], env=v.env, text=True).strip()
                streams = json.loads(subprocess.check_output(["pactl", "-f", "json", "list", "sink-inputs"], env=v.env))
                for stream in streams:
                    if stream.get("properties", {}).get("application.process.id") == str(v.proc.pid):
                        subprocess.run(["pactl", "move-sink-input", str(stream["index"]), default_sink], env=v.env)
                for module in reversed(v.audio_modules):
                    subprocess.run(["pactl", "unload-module", module], env=v.env)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
